package zebra

// SolvePuzzle solves the Zebra Puzzle (see .docs/instructions.md) and
// reports the nationality of the resident who drinks water and the
// nationality of the resident who owns the zebra.

const numHouses = 5

// Attribute indices into grid.values.
const (
	color = iota
	nation
	pet
	drink
	cigarette
	numAttributes
)

// attributeValues[attr] lists the five possible values for each attribute.
var attributeValues = [numAttributes][]string{
	color:     {"red", "green", "ivory", "yellow", "blue"},
	nation:    {"Englishman", "Spaniard", "Ukrainian", "Norwegian", "Japanese"},
	pet:       {"dog", "snails", "fox", "horse", "zebra"},
	drink:     {"coffee", "tea", "milk", "water", "orange juice"},
	cigarette: {"Old Gold", "Kools", "Chesterfields", "Lucky Strike", "Parliaments"},
}

// Solution reports the answers to the two questions posed by the puzzle.
type Solution struct {
	DrinksWater string
	OwnsZebra   string
}

// grid holds the puzzle state: grid.values[attr][house].
// Unassigned cells hold the empty string.
type grid struct {
	values [numAttributes][numHouses]string
}

func (g *grid) value(attr, house int) string { return g.values[attr][house] }

// used reports whether value v has already been assigned to some house of
// attribute attr.
func (g *grid) used(attr int, v string) bool {
	for h := 0; h < numHouses; h++ {
		if g.values[attr][h] == v {
			return true
		}
	}
	return false
}

// adjacent reports whether houses a and b are next to each other.
func adjacent(a, b int) bool { return a+1 == b || b+1 == a }

// SolvePuzzle solves the Zebra Puzzle and returns the answers.
func SolvePuzzle() Solution {
	var g grid
	if !search(g, 0) {
		panic("zebra: puzzle has no solution")
	}
	answer := Solution{}
	for h := 0; h < numHouses; h++ {
		if g.value(drink, h) == "water" {
			answer.DrinksWater = g.value(nation, h)
		}
		if g.value(pet, h) == "zebra" {
			answer.OwnsZebra = g.value(nation, h)
		}
	}
	return answer
}

// search assigns one attribute at a time to all five houses, backtracking
// whenever a constraint is violated. It reports whether a complete,
// consistent assignment was found.
func search(g *grid, attr int) bool {
	if attr == numAttributes {
		return true
	}
	return searchHouse(g, attr, 0)
}

// searchHouse assigns attribute attr to houses house through 4.
func searchHouse(g *grid, attr, house int) bool {
	if house == numHouses {
		return search(g, attr+1)
	}
	for _, v := range attributeValues[attr] {
		if g.used(attr, v) {
			continue
		}
		g.values[attr][house] = v
		if consistent(g) && searchHouse(g, attr, house+1) {
			return true
		}
		g.values[attr][house] = ""
	}
	return false
}

// consistent reports whether the partially filled grid violates any of the
// 15 statements. Constraints whose relevant cells are not yet assigned are
// deferred until those cells are filled.
func consistent(g *grid) bool {
	for h := 0; h < numHouses; h++ {
		c := g.value(color, h)
		n := g.value(nation, h)
		p := g.value(pet, h)
		d := g.value(drink, h)
		k := g.value(cigarette, h)

		// 2. The Englishman lives in the red house.
		if !compatible(n, "Englishman", c, "red") {
			return false
		}
		// 3. The Spaniard owns the dog.
		if !compatible(n, "Spaniard", p, "dog") {
			return false
		}
		// 4. Coffee is drunk in the green house.
		if !compatible(d, "coffee", c, "green") {
			return false
		}
		// 5. The Ukrainian drinks tea.
		if !compatible(n, "Ukrainian", d, "tea") {
			return false
		}
		// 7. The Old Gold smoker owns snails.
		if !compatible(k, "Old Gold", p, "snails") {
			return false
		}
		// 8. Kools are smoked in the yellow house.
		if !compatible(k, "Kools", c, "yellow") {
			return false
		}
		// 13. The Lucky Strike smoker drinks orange juice.
		if !compatible(k, "Lucky Strike", d, "orange juice") {
			return false
		}
		// 14. The Japanese smokes Parliaments.
		if !compatible(n, "Japanese", k, "Parliaments") {
			return false
		}

		// 10. The Norwegian lives in the first house.
		if h == 0 && n != "" && n != "Norwegian" {
			return false
		}
		// 15. The Norwegian lives next to the blue house. The only house
		// next to the first house is the second, so it must be blue.
		if h == 1 && c != "" && c != "blue" {
			return false
		}
		// 9. Milk is drunk in the middle house.
		if h == 2 && d != "" && d != "milk" {
			return false
		}
	}

	// 6. The green house is immediately to the right of the ivory house.
	for h := 0; h < numHouses; h++ {
		c := g.value(color, h)
		if c == "green" && h > 0 && g.value(color, h-1) != "" && g.value(color, h-1) != "ivory" {
			return false
		}
		if c == "ivory" && h < numHouses-1 && g.value(color, h+1) != "" && g.value(color, h+1) != "green" {
			return false
		}
	}

	// 11. The man who smokes Chesterfields lives in the house next to the
	// man with the fox.
	for h := 0; h < numHouses; h++ {
		if g.value(pet, h) != "fox" {
			continue
		}
		for h2 := 0; h2 < numHouses; h2++ {
			if g.value(cigarette, h2) == "Chesterfields" && !adjacent(h, h2) {
				return false
			}
		}
	}

	// 12. Kools are smoked in the house next to the house where the horse
	// is kept.
	for h := 0; h < numHouses; h++ {
		if g.value(pet, h) != "horse" {
			continue
		}
		for h2 := 0; h2 < numHouses; h2++ {
			if g.value(cigarette, h2) == "Kools" && !adjacent(h, h2) {
				return false
			}
		}
	}

	return true
}

// compatible reports whether two values from different attributes of the
// same house satisfy an "X is Y" style constraint, treating the empty
// string as "not yet assigned".
func compatible(a, aWant, b, bWant string) bool {
	if a == aWant && b != "" && b != bWant {
		return false
	}
	if b == bWant && a != "" && a != aWant {
		return false
	}
	return true
}

